using System.Collections.Generic;

namespace AnomalyArena
{

    public static class WeaponGuide
    {

        static Dictionary<(WeaponForm, int), (string how, string backfire)> Table() => new()
        {
            { (WeaponForm.Rifle, 0), (ArenaText.Pair("Hold to charge, release to fire a round that pierces a whole straight line; the fuller the charge, the harder it hits and the farther it pushes.","Hold to charge, release to fire a round that pierces a whole straight line; the fuller the charge, the harder it hits and the farther it pushes."), ArenaText.Pair($"You walk very slowly while charging, and enemy attacks hit you for {Percent(Tuning.chargeDamageTaken - 1f)}% more.",$"You walk very slowly while charging, and enemy attacks hit you for {Percent(Tuning.chargeDamageTaken - 1f)}% more.")) },
            { (WeaponForm.Rifle, 1), (ArenaText.Pair("Hold to fire a stream of rounds; a round bounces off a wall once. Reload when the clip runs out.","Hold to fire a stream of rounds; a round bounces off a wall once. Reload when the clip runs out."), ArenaText.Pair("Rounds fly out from your back.","Rounds fly out from your back.")) },
            { (WeaponForm.Knife, 0), (ArenaText.Pair("The blade bounces back and forth between a few nearby enemies, then flies back to where you stood when you threw it.","The blade bounces back and forth between a few nearby enemies, then flies back to where you stood when you threw it."), ArenaText.Pair("On its way back the blade cuts everything on its path, enemies and you alike.","On its way back the blade cuts everything on its path, enemies and you alike.")) },
            { (WeaponForm.Knife, 1), (ArenaText.Pair("The chain blade hooks an enemy and pulls it in front of you as a shield that stops projectiles; click again to fling it into other enemies, into walls or into a black hole.","The chain blade hooks an enemy and pulls it in front of you as a shield that stops projectiles; click again to fling it into other enemies, into walls or into a black hole."), ArenaText.Pair("As it pulls the enemy in, it drags you toward the enemy too: you meet halfway.","As it pulls the enemy in, it drags you toward the enemy too: you meet halfway.")) },
            { (WeaponForm.RocketLauncher, 0), (ArenaText.Pair("Marks the ground under the cursor; a moment later a rocket falls from the sky and blasts the area.","Marks the ground under the cursor; a moment later a rocket falls from the sky and blasts the area."), ArenaText.Pair("The blast is delayed, and it hurts you and enemies alike.","The blast is delayed, and it hurts you and enemies alike.")) },
            { (WeaponForm.RocketLauncher, 1), (ArenaText.Pair("You become the rocket and charge out, hitting every enemy on the way.","You become the rocket and charge out, hitting every enemy on the way."), ArenaText.Pair("Hitting a wall costs you HP; a black hole on the path swallows you and kills you outright.","Hitting a wall costs you HP; a black hole on the path swallows you and kills you outright.")) },
            { (WeaponForm.ScatterCannon, 0), (ArenaText.Pair("Two heavy blasts in a short cone; the closer the target, the higher the damage. Two shots per reload.","Two heavy blasts in a short cone; the closer the target, the higher the damage. Two shots per reload."), ArenaText.Pair("Each reload throws two hot shells to the ground at your sides; a moment later they flare up into small fires that burn whoever steps on them, you included.","Each reload throws two hot shells to the ground at your sides; a moment later they flare up into small fires that burn whoever steps on them, you included.")) },
            { (WeaponForm.ScatterCannon, 1), (ArenaText.Pair("Hold to gather all the pellets of one shell into a single point, then fire them as a rapid burst that reaches far.","Hold to gather all the pellets of one shell into a single point, then fire them as a rapid burst that reaches far."), ArenaText.Pair("The recoil is huge: it shoves you a long way back in one go; a wall behind you does not hurt.","The recoil is huge: it shoves you a long way back in one go; a wall behind you does not hurt.")) },
            { (WeaponForm.Flamethrower, 0), (ArenaText.Pair("Hold to spray fire forward and ignite the enemies in the cone.","Hold to spray fire forward and ignite the enemies in the cone."), ArenaText.Pair("If you are hit while spraying, the tank on your back bursts, burning the enemies around you and setting you alight at once.","If you are hit while spraying, the tank on your back bursts, burning the enemies around you and setting you alight at once.")) },
            { (WeaponForm.Flamethrower, 1), (ArenaText.Pair("Lobs a fireball that leaves a patch of burning ground where it lands.","Lobs a fireball that leaves a patch of burning ground where it lands."), ArenaText.Pair("Standing in your own fire burns you too.","Standing in your own fire burns you too.")) },
            { (WeaponForm.CryoCannon, 0), (ArenaText.Pair("Fires three flying ice shards in a fan, at most one per enemy each shot; a frozen target takes double damage.","Fires three flying ice shards in a fan, at most one per enemy each shot; a frozen target takes double damage."), ArenaText.Pair("Where a shard stops it leaves an ice patch; you and enemies slip on it, starting, stopping and turning only gradually (not bosses or Spires).","Where a shard stops it leaves an ice patch; you and enemies slip on it, starting, stopping and turning only gradually (not bosses or Spires).")) },
            { (WeaponForm.CryoCannon, 1), (ArenaText.Pair("Hold to spray snow forward; enemies freeze quickly, and keeping the spray on keeps them frozen.","Hold to spray snow forward; enemies freeze quickly, and keeping the spray on keeps them frozen."), ArenaText.Pair("While you spray, snow builds up at your feet; standing in it stacks Frost on you (never enough to freeze).","While you spray, snow builds up at your feet; standing in it stacks Frost on you (never enough to freeze).")) },
            { (WeaponForm.ArcCoil, 0), (ArenaText.Pair("An arc hits the nearest enemy in a cone ahead of your aim, then jumps several times between nearby enemies, never through a wall; with no enemy ahead it does not discharge (built-in Lightning element).","An arc hits the nearest enemy in a cone ahead of your aim, then jumps several times between nearby enemies, never through a wall; with no enemy ahead it does not discharge (built-in Lightning element)."), ArenaText.Pair("When there are not enough enemies nearby, the jumps that find no target come back into you, and enough of them paralyse you.","When there are not enough enemies nearby, the jumps that find no target come back into you, and enough of them paralyse you.")) },
            { (WeaponForm.ArcCoil, 1), (ArenaText.Pair("Charges as you walk with it in your hand, faster with enemies close by; click to release all of it and shock everything around you. A full charge hits harder.","Charges as you walk with it in your hand, faster with enemies close by; click to release all of it and shock everything around you. A full charge hits harder."), ArenaText.Pair("Hold a full charge too long without releasing it and it discharges into you by itself.","Hold a full charge too long without releasing it and it discharges into you by itself.")) },
            { (WeaponForm.SporeLauncher, 0), (ArenaText.Pair("Lobs a pod that bursts into a long-lingering poison cloud (built-in Poison element).","Lobs a pod that bursts into a long-lingering poison cloud (built-in Poison element)."), ArenaText.Pair("When the cloud fades it leaves spore pods that burst under whoever steps on them: enemies are poisoned, and you lose HP too (without the poison).","When the cloud fades it leaves spore pods that burst under whoever steps on them: enemies are poisoned, and you lose HP too (without the poison).")) },
            { (WeaponForm.SporeLauncher, 1), (ArenaText.Pair("Hold to fire poison needles; each one stacks Poison on the enemy. Reload when the clip runs out.","Hold to fire poison needles; each one stacks Poison on the enemy. Reload when the clip runs out."), ArenaText.Pair("Each reload, the spent venom sac bursts into a small poison mist where you stand: enemies in it are poisoned, and you lose HP while you stay in it (without the poison).","Each reload, the spent venom sac bursts into a small poison mist where you stand: enemies in it are poisoned, and you lose HP while you stay in it (without the poison).")) },
            { (WeaponForm.Railgun, 0), (ArenaText.Pair("After a short wind-up it fires a rail beam that pierces a straight line and ignores the Shield's damage cut; each target behind the first takes less.","After a short wind-up it fires a rail beam that pierces a straight line and ignores the Shield's damage cut; each target behind the first takes less."), ArenaText.Pair("The recoil shoves you far back, maybe into a crowd or a black hole (a wall behind you does not hurt). You move at half speed during the wind-up.","The recoil shoves you far back, maybe into a crowd or a black hole (a wall behind you does not hurt). You move at half speed during the wind-up.")) },
            { (WeaponForm.Railgun, 1), (ArenaText.Pair("A single shot of very high damage that executes low-HP enemies outright; a kill gives part of the cooldown back at once and makes the next shot hit harder.","A single shot of very high damage that executes low-HP enemies outright; a kill gives part of the cooldown back at once and makes the next shot hit harder."), ArenaText.Pair("If a shot kills no enemy (a boss it hits but does not kill does not count), the surplus charge shocks you and the gun goes into a long cooldown.","If a shot kills no enemy (a boss it hits but does not kill does not count), the surplus charge shocks you and the gun goes into a long cooldown.")) },
            { (WeaponForm.Minigun, 0), (ArenaText.Pair("Hold to fire; the fire rate climbs as it spins.","Hold to fire; the fire rate climbs as it spins."), ArenaText.Pair($"The faster it spins, the slower you can turn your aim, and it slowly pushes you back (about {Tuning.spinUpRetreatSpeed:0.#} cells a second at full spin; a wall behind you does not hurt).",$"The faster it spins, the slower you can turn your aim, and it slowly pushes you back (about {Tuning.spinUpRetreatSpeed:0.#} cells a second at full spin; a wall behind you does not hurt).")) },
            { (WeaponForm.Minigun, 1), (ArenaText.Pair("Full fire rate from the first shot, but sustained fire keeps building heat.","Full fire rate from the first shot, but sustained fire keeps building heat."), ArenaText.Pair("When it overheats it explodes around you, then stops firing for a while.","When it overheats it explodes around you, then stops firing for a while.")) },
            { (WeaponForm.SwarmLauncher, 0), (ArenaText.Pair("Fires a swarm of micro-missiles that home in on nearby enemies.","Fires a swarm of micro-missiles that home in on nearby enemies."), ArenaText.Pair($"Each missile locks a different visible enemy within {BarrageRange:0.#} cells; when there are too few, up to {Tuning.barrageSelfLockMax} spare missiles lock onto you and turn back to blast you, and the rest fly straight on.",$"Each missile locks a different visible enemy within {BarrageRange:0.#} cells; when there are too few, up to {Tuning.barrageSelfLockMax} spare missiles lock onto you and turn back to blast you, and the rest fly straight on.")) },
            { (WeaponForm.SwarmLauncher, 1), (ArenaText.Pair("A string of blasts walks away from you in a straight line.","A string of blasts walks away from you in a straight line."), ArenaText.Pair("The first blast is right in front of you; walk forward and you walk into it.","The first blast is right in front of you; walk forward and you walk into it.")) },
            { (WeaponForm.OrbitBlades, 0), (ArenaText.Pair("Blades circle you; enemies they touch take damage and are pushed outward.","Blades circle you; enemies they touch take damage and are pushed outward."), ArenaText.Pair("They also knock pickups (XP, health and energy orbs) and corpses away.","They also knock pickups (XP, health and energy orbs) and corpses away.")) },
            { (WeaponForm.OrbitBlades, 1), (ArenaText.Pair("Blades circle you; enemies they touch take damage and are pulled inward.","Blades circle you; enemies they touch take damage and are pulled inward."), ArenaText.Pair("Enemies get dragged right into your face.","Enemies get dragged right into your face.")) },

            { (WeaponForm.SentryDrone, 0), (ArenaText.Pair($"The drone fires rapidly at nearby enemies on its own, {Tuning.gunnerClip} rounds to a magazine.",$"The drone fires rapidly at nearby enemies on its own, {Tuning.gunnerClip} rounds to a magazine."), ArenaText.Pair($"When a magazine runs dry the drone drops to the ground to cool down; step on it to send it back up, or wait {N(Tuning.gunnerAutoReturn)} s.",$"When a magazine runs dry the drone drops to the ground to cool down; step on it to send it back up, or wait {N(Tuning.gunnerAutoReturn)} s.")) },
            { (WeaponForm.SentryDrone, 1), (ArenaText.Pair($"The drone's tractor beam drags a lone enemy {N(Tuning.whirlMinRange)}–{N(WhirlRange)} cells away, throws it and slams it down; it and the enemies where it lands take damage.",$"The drone's tractor beam drags a lone enemy {N(Tuning.whirlMinRange)}–{N(WhirlRange)} cells away, throws it and slams it down; it and the enemies where it lands take damage."), ArenaText.Pair($"It always slams the enemy where you stood {N(Tuning.whirlAfterimageSeconds)} s ago; your afterimage marks the spot.",$"It always slams the enemy where you stood {N(Tuning.whirlAfterimageSeconds)} s ago; your afterimage marks the spot.")) },
            { (WeaponForm.ShieldRing, 0), (ArenaText.Pair($"Opens a ring-shaped force field: enemies close to you move {P(1f - Tuning.deflectSlow)}% slower, and incoming projectiles have a {P(Tuning.deflectChance)}% chance to be deflected and fizzle. Enemies in the field take a light {N(Ring.damageA)} damage every {N(Ring.cooldownA)} s, which is how an infused element gets onto them.",$"Opens a ring-shaped force field: enemies close to you move {P(1f - Tuning.deflectSlow)}% slower, and incoming projectiles have a {P(Tuning.deflectChance)}% chance to be deflected and fizzle. Enemies in the field take a light {N(Ring.damageA)} damage every {N(Ring.cooldownA)} s, which is how an infused element gets onto them."), ArenaText.Pair($"Your own bullets and lobbed shots leaving the ring also have a {P(Tuning.deflectChance)}% chance to be knocked off course at its edge.",$"Your own bullets and lobbed shots leaving the ring also have a {P(Tuning.deflectChance)}% chance to be knocked off course at its edge.")) },
            { (WeaponForm.ShieldRing, 1), (ArenaText.Pair($"After a while without an enemy hit it raises an Energy Shield that blocks one hit; each block gives you {N(Tuning.drainBlockEnergy)} Energy. Once infused, each block also releases a burst of its element on the enemies within {N(Tuning.drainInfuseRadius)} cells.",$"After a while without an enemy hit it raises an Energy Shield that blocks one hit; each block gives you {N(Tuning.drainBlockEnergy)} Energy. Once infused, each block also releases a burst of its element on the enemies within {N(Tuning.drainInfuseRadius)} cells."), ArenaText.Pair($"Take another hit within {N(Tuning.drainOverloadSeconds)} s after the shield breaks and you lose {N(Tuning.drainOverloadEnergy)} Energy (once per break).",$"Take another hit within {N(Tuning.drainOverloadSeconds)} s after the shield breaks and you lose {N(Tuning.drainOverloadEnergy)} Energy (once per break).")) },
        };

        static WeaponUpgradeTuning Tuning => GameManager.Instance && GameManager.Instance.runWeapons ? GameManager.Instance.runWeapons.upgrades : new WeaponUpgradeTuning();

        static WeaponRoster.Definition Ring
        {
            get
            {
                var weapons = GameManager.Instance ? GameManager.Instance.runWeapons : null;
                var definition = weapons && weapons.roster ? weapons.roster.Get(WeaponForm.ShieldRing) : null;
                return definition ?? new WeaponRoster.Definition { form = WeaponForm.ShieldRing, damageA = 1f, cooldownA = 1f };
            }
        }
        static float BarrageRange
        {
            get
            {
                var weapons = GameManager.Instance ? GameManager.Instance.runWeapons : null;
                var definition = weapons && weapons.roster ? weapons.roster.Get(WeaponForm.SwarmLauncher) : null;
                return definition != null ? definition.rangeA : 9f;
            }
        }

        static (string how, string backfire) Entry(WeaponForm form, int variant) =>
            Table().TryGetValue((form, variant == 0 ? 0 : 1), out var entry) ? entry : ("", "");

        public static string How(WeaponForm form, int variant) => Entry(form, variant).how;

        public static string Backfire(WeaponForm form, int variant) => Entry(form, variant).backfire + Stowed(form, variant);

        static string Stowed(WeaponForm form, int variant) => form == WeaponForm.ArcCoil && variant == 1
            ? ArenaText.Pair(" Stowed, it slowly loses its charge and its full-charge timer runs back; it never discharges while stowed."," Stowed, it slowly loses its charge and its full-charge timer runs back; it never discharges while stowed.")
            : "";

        static string Percent(float share) => (share * 100f).ToString("0.#");

        static float WhirlRange
        {
            get
            {
                var roster = GameManager.Instance && GameManager.Instance.runWeapons ? GameManager.Instance.runWeapons.roster : null;
                var definition = roster ? roster.Get(WeaponForm.SentryDrone) : null;
                return definition != null ? definition.rangeB : 12f;
            }
        }
        static string N(float value) => value.ToString("0.##");
        static string P(float share) => (share * 100f).ToString("0.#");
    }
}
